function exportCSV(which){const s=settle(G);
 if(which==='roster')dl('av1_roster.csv',csv([['#','Name','Email','Note'],...G.roster.map((r,i)=>[i+1,r.name,r.email,r.note])]),'text/csv');
 if(which==='tracker')dl('av1_tracker.csv',csv([['Item','Date','Status','Booked by','Confirmation #','Deposit (EUR)','Deposit paid by','Notes'],...G.tracker.map(r=>[r.item,r.date,r.status,pn(r.bookedBy),r.conf,r.deposit,pn(r.depositBy),r.notes])]),'text/csv');
 if(which==='ledger'){const rows=[['Line item','Total (EUR)','Split among','Per person (EUR)','Paid by','Notes',...G.roster.map((r,i)=>'Split: '+nm(i))],...G.ledger.map(r=>{const k=r.split.filter(Boolean).length;return[r.item,r.total,r.split.map((b,i)=>b?nm(i):null).filter(Boolean).join('; '),k?(cents(r.total)/k/100).toFixed(2):'',pn(r.paidBy),r.notes,...r.split.map(TB)]}),[],['Settlement'],['Traveler','Share of all lines','Paid','Share of paid lines','Balance'],...G.roster.map((r,i)=>[nm(i),(s.shareAll[i]/100).toFixed(2),(s.paid[i]/100).toFixed(2),(s.share[i]/100).toFixed(2),(s.net[i]/100).toFixed(2)]),[],['Transfers'],['From','To','Amount (EUR)'],...s.transfers.map(t=>[nm(t.from),nm(t.to),(t.amount/100).toFixed(2)])];dl('av1_ledger.csv',csv(rows),'text/csv')}}
function exportJSON(){dl('av1_group_'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(Object.assign({v:GVER,version:GVER,app:'av1-group',exportedAt:new Date().toISOString()},clone(G)),null,1),'application/json')}

// ---- Sheet CSV import (File > Download > CSV of the Roster, Bookings & Deposits, Expenses & Splits tabs) ----
function parseCSV(t){t=t.replace(/^\ufeff/,'');const rows=[];let row=[],f='',i=0,qd=false;
 for(;i<t.length;i++){const c=t[i];
  if(qd){if(c==='"'){if(t[i+1]==='"'){f+='"';i++}else qd=false}else f+=c}
  else if(c==='"')qd=true;else if(c===','){row.push(f);f=''}else if(c==='\n'||c==='\r'){if(c==='\r'&&t[i+1]==='\n')i++;row.push(f);rows.push(row);row=[];f=''}else f+=c}
 if(f!==''||row.length){row.push(f);rows.push(row)}return rows}
const H=s=>String(s||'').replace(/\s+/g,' ').trim().toLowerCase();
const unq=s=>{s=String(s??'').trim();return s.startsWith("'")&&/^'[=+\-@]/.test(s)?s.slice(1):s};
function amount(s){s=String(s??'').replace(/[€\s\u00a0]|EUR/gi,'');if(s==='')return'';
 if(/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(s))s=s.replace(/,/g,'');else if(/^\d+,\d{1,2}$/.test(s))s=s.replace(',','.');
 const n=Number(s);return isFinite(n)&&n>=0&&/^[\d.]+$/.test(s)?n.toFixed(2):null}
function bool(s){s=H(s);if(['true','yes','y','1','x','✓'].includes(s))return true;if(['false','no','n','0',''].includes(s))return false;return null}
function sheetKind(h){if(h[0]==='traveler')return'balances';if(h.includes('line item')&&h.some(x=>x.startsWith('total')))return'expenses';if(h.includes('item')&&h.includes('status'))return'bookings';if(h.includes('name')&&(h[0]==='#'||h.includes('email')))return'roster';return null}
const TABN={roster:'Roster',bookings:'Bookings & Deposits',expenses:'Expenses & Splits'};
/* files: [{name,text}] -> {state, summary[], errors[]}; all-or-nothing */
function importSheetCSV(files){const errors=[],summary=[],E=m=>{if(errors.length<40)errors.push(m)};const parsed={};
 const rows0=(p,col)=>`"${p.raw[col]}"`;
 for(const f of files){const rows=parseCSV(f.text);const hi=rows.findIndex(r=>r.some(c=>c.trim()!==''));if(hi<0){E(`${f.name}: the file is empty.`);continue}
  const h=rows[hi].map(H),kind=sheetKind(h);
  if(kind==='balances'){E(`${f.name}: this is the Balances tab. It is computed from the other tabs and is never imported.`);continue}
  if(!kind){E(`${f.name}: not a Roster, Bookings & Deposits or Expenses & Splits export (first row: ${rows[hi].slice(0,4).join(', ')}).`);continue}
  if(parsed[kind]){E(`${f.name}: a second ${TABN[kind]} file was chosen; pick one per tab.`);continue}
  const body=[];for(let i=hi+1;i<rows.length;i++){if(kind==='expenses'&&H(rows[i][0])==='settlement')break;if(rows[i].every(c=>c.trim()===''))continue;body.push({n:i+1,c:rows[i]})}
  parsed[kind]={f:f.name,h,raw:rows[hi],body}}
 const cand=clone(G),oldRoster=G.roster;
 if(parsed.roster){const {f,h,body}=parsed.roster,ci=k=>h.indexOf(k),cell=(r,k)=>ci(k)>=0?unq(r.c[ci(k)]):'';
  if(ci('name')<0)E(`${f}: no “Name” column.`);
  else{const rows=body.filter(r=>cell(r,'name')!==''||cell(r,'email')!==''||cell(r,'note')!==''); // a numbered row with no name, email or note is a placeholder
   const seen=new Map();rows.forEach(r=>{const k=H(cell(r,'name'));if(k==='')E(`${f} row ${r.n}: Name is empty.`);else if(seen.has(k))E(`${f} row ${r.n}: “${cell(r,'name')}” is listed twice (also row ${seen.get(k)}); names must be unique.`);else seen.set(k,r.n)});
   if(rows.length<1||rows.length>MAXT)E(`${f}: ${rows.length} travelers found; the roster must have 1 to ${MAXT}.`);
   else if(!errors.length){cand.roster=rows.map(r=>({name:cell(r,'name'),email:cell(r,'email'),note:cell(r,'note')}));summary.push(`Roster: ${plural(cand.roster.length)}`)}}}
 const NN=cand.roster.length,dispName=(r,i)=>r.name||('Traveler '+(i+1));
 const who=new Map(cand.roster.map((r,i)=>[H(dispName(r,i)),String(i)]));
 /* roster changed but a dependent tab was not chosen: carry its people over by name, and refuse rather than guess when someone it uses is gone */
 const rosterChanged=parsed.roster&&JSON.stringify(oldRoster.map(r=>H(r.name)))!==JSON.stringify(cand.roster.map(r=>H(r.name)));
 if(rosterChanged&&!errors.length){const map=oldRoster.map((r,i)=>who.get(H(dispName(r,i))));
  const re=(v,where)=>{if(v===''||v==null)return'';const k=map[+v];if(k===undefined){E(`${where} uses ${dispName(oldRoster[+v],+v)}, who is not in the new roster. Choose the ${where.startsWith('Tracker')?'Bookings & Deposits':'Expenses & Splits'} CSV too.`);return''}return k};
  if(!parsed.bookings)cand.tracker.forEach((r,i)=>{r.bookedBy=re(r.bookedBy,`Tracker row ${i+1}`);r.depositBy=re(r.depositBy,`Tracker row ${i+1}`)});
  if(!parsed.expenses){const added=cand.roster.filter((r,i)=>!map.includes(String(i))).map(dispName),dropped=oldRoster.filter((r,i)=>map[i]===undefined).map(dispName);
   cand.ledger.forEach((r,i)=>{r.paidBy=re(r.paidBy,`Ledger line ${i+1}`);const sp=Array(NN).fill(false);r.split.forEach((b,j)=>{if(map[j]!==undefined)sp[+map[j]]=b});r.split=sp});
   if(added.length)summary.push(`Note: ${added.join(', ')} ${added.length>1?'are':'is'} not in any ledger split yet (the Expenses & Splits CSV was not chosen).`);
   if(dropped.length)summary.push(`Note: ${dropped.join(', ')} left the roster; their ledger shares moved to the others on each line.`)}}
 const person=(v,where,col)=>{v=unq(v);if(v==='')return'';const k=who.get(H(v));if(k===undefined){E(`${where}: “${col}” = "${v}" is not a name in the roster (${cand.roster.map(r=>r.name).join(', ')}).`);return''}return k};
 if(parsed.bookings){const {f,h,body}=parsed.bookings,need=['item','date','status','booked by','confirmation #','deposit (eur)','deposit paid by','notes'];
  const miss=need.filter(k=>!h.includes(k));if(miss.length)E(`${f}: missing column(s): ${miss.join(', ')}.`);
  else{const g=(r,k)=>unq(r.c[h.indexOf(k)]);cand.tracker=body.map(r=>{const w=`${f} row ${r.n}`;
   let st=g(r,'status');const S2=STATUSES.find(x=>H(x)===H(st));if(st==='')st='Not booked';else if(!S2)E(`${w}: status "${st}" is not one of ${STATUSES.join(' / ')}.`);else st=S2;
   const dep=amount(g(r,'deposit (eur)'));if(dep===null)E(`${w}: deposit "${g(r,'deposit (eur)')}" is not an amount.`);
   return{item:g(r,'item'),date:g(r,'date'),status:STATUSES.includes(st)?st:'Not booked',bookedBy:person(g(r,'booked by'),w,'Booked by'),conf:g(r,'confirmation #'),deposit:dep||'',depositBy:person(g(r,'deposit paid by'),w,'Deposit paid by'),notes:g(r,'notes')}});
   summary.push(`Bookings & Deposits: ${cand.tracker.length} rows`)}}
 if(parsed.expenses){const {f,h,body}=parsed.expenses,ti=h.findIndex(x=>x.startsWith('total')),need=['line item','paid by','notes'];
  const miss=need.filter(k=>!h.includes(k));if(miss.length)E(`${f}: missing column(s): ${miss.join(', ')}.`);
  else{const blank=c=>body.every(r=>!bool(r.c[c])); // a "Split: " column for an empty roster slot in the Sheet, with nothing ticked, is ignored
   const sc=h.map((x,i)=>x.startsWith('split:')&&!(x.slice(6).trim()===''&&blank(i))?i:-1).filter(i=>i>=0);let map=null;
   if(sc.length){const byName=sc.map(i=>who.get(H(h[i].slice(6))));
    if(byName.every(x=>x!==undefined)&&new Set(byName).size===sc.length&&sc.length===NN)map=sc.map((col,k)=>[col,+byName[k]]);
    else if(sc.length===NN&&!byName.some(x=>x!==undefined)){map=sc.map((col,k)=>[col,k]);summary.push(`Note: the “Split:” column names do not match the roster names, so they were read in roster order.`)}
    else{const unknown=sc.filter((c,k)=>byName[k]===undefined).map(c=>rows0(parsed.expenses,c)),missing=cand.roster.map(dispName).filter((n,i)=>!byName.includes(String(i)));
     E(`${f}: ${sc.length} “Split:” columns for a roster of ${plural(NN)}.`+(unknown.length?` Not in the roster: ${unknown.join(', ')}.`:'')+(missing.length?` No column for: ${missing.join(', ')}.`:'')+(new Set(byName.filter(x=>x!==undefined)).size<byName.filter(x=>x!==undefined).length?' A name has two columns.':'')+' Each traveler needs exactly one “Split: <name>” column (choose the Roster CSV too if you added someone).')}}
   else if(!h.includes('split among'))E(`${f}: no “Split: <name>” columns (or “Split among”).`);
   const g=(r,k)=>unq(r.c[h.indexOf(k)]);
   cand.ledger=body.map(r=>{const w=`${f} row ${r.n}`;const tot=amount(r.c[ti]);if(tot===null)E(`${w}: total "${r.c[ti]}" is not an amount.`);
    let split=Array(NN).fill(false);
    if(map)map.forEach(([col,k])=>{const b=bool(r.c[col]);if(b===null)E(`${w}: “${h[col]}” must be TRUE or FALSE (got "${r.c[col]}").`);else split[k]=b});
    else String(g(r,'split among')).split(';').map(s=>s.trim()).filter(Boolean).forEach(n=>{const k=who.get(H(n));if(k===undefined)E(`${w}: “Split among” name "${n}" is not in the roster.`);else split[+k]=true});
    return{item:g(r,'line item'),total:tot||'',split,paidBy:person(g(r,'paid by'),w,'Paid by'),notes:g(r,'notes')}});
   summary.push(`Expenses & Splits: ${cand.ledger.length} lines`)}}
 if(errors.length)return{errors};
 const n=normalize(cand);return n.state?{state:n.state,summary}:{errors:n.errors}}
window.importSheetCSV=importSheetCSV;

function initGroup(){
 document.getElementById('gCsvR').onclick=()=>exportCSV('roster');document.getElementById('gCsvT').onclick=()=>exportCSV('tracker');document.getElementById('gCsvL').onclick=()=>exportCSV('ledger');
 document.getElementById('gJson').onclick=exportJSON;
 document.getElementById('gReset').onclick=()=>{if(confirm('Reset roster, tracker and ledger to the defaults? Your edits in this browser will be lost (export JSON first to keep them).'))applyG(clone(GROUP),['Reset to the defaults.'])};
 document.getElementById('gImport').onchange=e=>{const f=e.target.files[0];e.target.value='';if(!f)return;f.text().then(t=>{let s;
  try{s=JSON.parse(t)}catch(err){showMsg([`${f.name} was not imported: it is not valid JSON (${err.message}). Nothing was changed.`],true);return}
  const n=normalize(s,f.name);if(!n.state){showMsg([`${f.name} was not imported. Nothing was changed.`,...n.errors],true);return}
  applyG(n.state,[`Imported ${f.name}.`,...n.notes])})};
 document.getElementById('gImportCsv').onchange=e=>{const fs=[...e.target.files];e.target.value='';if(!fs.length)return;
  Promise.all(fs.map(f=>f.text().then(text=>({name:f.name,text})))).then(files=>{const r=importSheetCSV(files);
   if(!r.state){showMsg(['Sheet CSV not imported. Nothing was changed.',...r.errors],true);return}
   applyG(r.state,['Imported from the Sheet CSV: '+r.summary.filter(x=>!x.startsWith('Note')).join(' · ')+'.',...r.summary.filter(x=>x.startsWith('Note'))])})};
 renderG();if(migratedFrom){saveG();showMsg([`Moved your earlier Group data from ${migratedFrom} to ${GKEY}. The old copy is left untouched.`,...loadNotes],false)}
 else if(textMigrated){saveG();showMsg(['Updated the default booking-tracker text for a group of 9. Rows you edited or booked are unchanged.',...loadNotes],false)}}
initGroup();


/* Redesign: fill booking pills [data-hut-badge] from the Group tracker. Read-only; re-runs after every renderG().
   A pill names its hut by stable id (data-hut-id → D.hutstatus) and matches a tracker item that says "Rifugio <full hut name>" / "Rif. <full hut name>". */
const HUTNAME=Object.fromEntries(D.hutstatus.map(h=>[h.id,String(h.hut).replace(/^Rif(ugio|\.)\s+/,'')]));
const reEsc=t=>t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
function hutName(b){const id=b.dataset.hutId;if(id&&HUTNAME[id])return HUTNAME[id];
 const m=/^Rif(?:ugio|\.)\s+(.+?)\s*(?:[≈(,]|\d|$)/.exec(b.dataset.hutBadge||'');return m?m[1].trim():''}
/* pill pulse: .is-changed when a pill's status changes (not on first fill); CSS animates it only without reduced motion */
const lastPill=new WeakMap();
function pulse(b,k){const was=lastPill.get(b);lastPill.set(b,k);if(was===undefined||was===k||reduceMotion)return;
 b.classList.remove('is-changed');void b.offsetWidth;b.classList.add('is-changed');const off=()=>b.classList.remove('is-changed');b.addEventListener('animationend',off,{once:true});setTimeout(off,1200)}
function hutBadges(){if(typeof G==='undefined'||!G||!Array.isArray(G.tracker))return;
 const S={'Not booked':['not-booked','Not booked'],'Requested':['pending','Pending'],'Confirmed':['booked','Booked'],'Paid':['booked','Booked · paid'],'Cancelled':['cancelled','Cancelled']};
 document.querySelectorAll('[data-hut-badge]').forEach(b=>{const name=hutName(b),card=!!b.closest('.day');
  if(!name){b.dataset.status='none';b.textContent=card?'No hut night':'';b.removeAttribute('title');return}
  const re=new RegExp('\\bRif(?:ugio|\\.)\\s+'+reEsc(name).replace(/\\s+/g,'\\s+')+'(?![\\p{L}])','iu'),hits=G.tracker.filter(r=>re.test(String(r.item||'')));
  const row=hits.find(r=>/hut night/i.test(r.item))||hits[0];
  if(!row){b.textContent='';delete b.dataset.status;b.removeAttribute('title');return}
  const [k,t]=S[row.status]||['none',String(row.status||'Not booked')];pulse(b,k);b.dataset.status=k;b.textContent=t;b.title='Rifugio '+name+' booking: '+row.status+' (Group → Booking tracker)'})}
if(typeof renderG==='function'){const _renderG=renderG;renderG=function(){const r=_renderG.apply(this,arguments);hutBadges();return r}}
hutBadges();

/* ==== UI upgrades (HANDOFF-DEV.md): Sun/Night, follow the day, countdown, bento, view transitions, print date ====
   Hooks live in template_av1.html + upgrades.css. Everything here reads D, G.tracker and G.roster, so roster size,
   hut names and nights come from the data (no names or per-day numbers in this code). */
const $1=(q,r=document)=>r.querySelector(q),$all=(q,r=document)=>[...r.querySelectorAll(q)];
const PHONE=matchMedia('(max-width:800px)');
const smooth=()=>reduceMotion?'auto':'smooth';
const STATUS={'Confirmed':['booked','Booked'],'Paid':['booked','Booked · paid'],'Requested':['pending','Pending'],'Not booked':['not-booked','Not booked'],'Cancelled':['cancelled','Cancelled']};
const stKey=st=>(STATUS[st]||STATUS['Not booked'])[0];
const escH=t=>String(t).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));

/* ---- Sun / Night (localStorage av1-mode: sun|night|auto; auto = follow prefers-color-scheme) ---- */
const MKEY='av1-mode',DARK=matchMedia('(prefers-color-scheme: dark)');
const MICO={sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',night:'<path d="M20 14.5A8 8 0 1 1 9.5 4a6.5 6.5 0 0 0 10.5 10.5Z"/>',auto:'<circle cx="12" cy="12" r="8"/><path d="M12 4a8 8 0 0 1 0 16Z" fill="currentColor"/>'};
/* the toggle cycles Auto → Sun → Night → Auto; Auto keeps following the system setting live */
const MNAME={auto:'Auto',sun:'Sun',night:'Night'},MNEXT={auto:'sun',sun:'night',night:'auto'};
const modePref=()=>{try{const m=localStorage.getItem(MKEY);return m==='sun'||m==='night'?m:'auto'}catch(e){return 'auto'}};
const modeNow=()=>{const m=modePref();return m==='auto'?(DARK.matches?'night':'sun'):m};
function chartColors(eff){if(!window.Chart)return;const cs=getComputedStyle(document.documentElement),C=Chart.defaults;
 const ink9=cs.getPropertyValue('--ink-900').trim()||'#15212b',ink6=cs.getPropertyValue('--ink-600').trim()||'#475563',grid=eff==='night'?'rgba(236,230,220,0.14)':'rgba(21,33,43,0.08)';
 C.color=ink6;C.borderColor=grid;C.scale.grid.color=grid;C.scale.ticks.color=ink6;C.scale.title.color=ink6;C.plugins.title.color=ink9;C.plugins.legend.labels.color=ink9;
 Object.values(Chart.instances).forEach(c=>{const o=c.options;Object.values(o.scales||{}).forEach(x=>{if(x.grid)x.grid.color=grid;if(x.ticks)x.ticks.color=ink6;if(x.title)x.title.color=ink6;if(x.border)x.border.color=grid});
  if(o.plugins){if(o.plugins.title)o.plugins.title.color=ink9;if(o.plugins.legend&&o.plugins.legend.labels)o.plugins.legend.labels.color=ink9}c.update('none')})}
function applyMode(){const eff=modeNow(),root=document.documentElement;
 if(eff==='night')root.dataset.mode='night';else delete root.dataset.mode;
 const tm=$1('meta[name="theme-color"]');if(tm){if(!tm.dataset.sun)tm.dataset.sun=tm.content;tm.content=eff==='night'?'#0d151c':tm.dataset.sun}
 const b=$1('#modeToggle');if(b){const pref=modePref(),state=pref==='auto'?'Auto (system, now '+MNAME[eff]+')':MNAME[pref];b.hidden=false;
  b.setAttribute('aria-label','Display: '+state+'. Tap for '+MNAME[MNEXT[pref]]+'.');b.dataset.modePref=pref;const l=$1('.lbl',b);if(l)l.textContent=MNAME[pref];const sv=$1('svg',b);if(sv)sv.innerHTML=MICO[pref]}
 chartColors(eff)}
{const b=$1('#modeToggle');if(b)b.addEventListener('click',()=>{try{localStorage.setItem(MKEY,MNEXT[modePref()])}catch(e){}applyMode()});
 DARK.addEventListener&&DARK.addEventListener('change',()=>{if(modePref()==='auto')applyMode()});applyMode()}

/* ---- elevation sparkline (cards + bento), scaled to the whole route's range ---- */
const EMIN=Math.min(...D.stages.map(s=>Math.min(...s.ele))),EMAX=Math.max(...D.stages.map(s=>Math.max(...s.ele)));
function sparkSvg(i,cls){const s=D.stages[i],W=200,H=44,last=s.cum[s.cum.length-1]||1,step=Math.max(1,Math.floor(s.ele.length/90)),y=e=>(H-2-(e-EMIN)/((EMAX-EMIN)||1)*(H-4)).toFixed(1);
 let p='';for(let k=0;k<s.ele.length;k+=step)p+=(k?'L':'M')+(s.cum[k]/last*W).toFixed(1)+','+y(s.ele[k]);p+='L'+W+','+y(s.ele[s.ele.length-1]);
 return `<svg${cls?` class="${cls}"`:''} viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-hidden="true" focusable="false"><path d="${p}L${W},${H}L0,${H}Z" fill="${s.color}" fill-opacity=".14"/><path d="${p}" fill="none" stroke="${s.color}" stroke-width="2" vector-effect="non-scaling-stroke" stroke-linejoin="round"/></svg>`}
D.stages.forEach((s,i)=>{const h=$1('#d'+i+'h');if(h&&!h.nextElementSibling?.classList.contains('day-spark'))h.insertAdjacentHTML('afterend',sparkSvg(i,'day-spark'))});

/* ---- Countdown (target from time[data-bento-start]) ---- */
function countdown(){const t=$1('time[data-bento-start]'),n=$1('[data-bento-countdown]'),l=$1('[data-bento-countdown-label]');if(!t||!n||!l)return;
 const start=new Date(t.getAttribute('datetime'));if(isNaN(start))return;
 if(!l.dataset.orig)l.dataset.orig=l.textContent;const where=l.dataset.orig.split('·').slice(1).join('·').trim();
 const ms=start-Date.now(),days=Math.ceil(ms/864e5),trip=D.stages.length,d=Math.floor(-ms/864e5)+1;
 if(ms>0){n.textContent=fmt(days);l.textContent=(days===1?'day':'days')+' to go'+(where?' · '+where:'')}
 else if(d<=trip){n.textContent='Day '+d;l.textContent='of '+trip+' · on the trail'}
 else{n.textContent='Done';l.textContent='Trip complete'}}
countdown();document.addEventListener('visibilitychange',()=>{if(!document.hidden)countdown()});

/* ---- Bento: route sparks, bookings, hut nights ---- */
const ini=nm=>{const w=String(nm||'').trim().split(/\s+/).filter(Boolean);return (w.length?w.map(x=>[...x][0]).join('').slice(0,2):'?').toUpperCase()};
function dayName(n){const t=$1('time[data-bento-start]'),st=t&&new Date(t.getAttribute('datetime'));if(!st||isNaN(st))return '';
 const d=new Date(st.getTime()+(n-1)*864e5);return d.toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',timeZone:'Europe/Rome'}).replace(',','')}
function bentoRoute(){const box=$1('[data-bento-sparks]');if(!box||box.dataset.done)return;box.dataset.done='1';
 box.innerHTML=D.stages.map((s,i)=>`<button type="button" class="spark" data-day="${i}" aria-pressed="false"><b><span aria-hidden="true" style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${s.color};margin-right:6px"></span>Day ${i+1}</b><span>${s.km.toFixed(1)} km · +${fmt(s.gain)} m · top ${fmt(Math.max(...s.ele))} m</span>${sparkSvg(i)}</button>`).join('');
 box.setAttribute('aria-busy','false');const e=$1('[data-bento-empty]',box.closest('.tile'));if(e)e.remove();
 box.addEventListener('click',ev=>{const b=ev.target.closest('.spark');if(!b)return;const i=+b.dataset.day;select(b.getAttribute('aria-pressed')==='true'?null:i,true)})}
function bentoBookings(){const tile=$1('[data-bento="bookings"]');if(!tile||typeof G==='undefined'||!G)return;
 const t=Array.isArray(G.tracker)?G.tracker:[],c={booked:0,pending:0,'not-booked':0,cancelled:0};t.forEach(r=>c[stKey(r.status)]++);
 const set=(k,v)=>$all(`[data-bento-count="${k}"]`,tile).forEach(x=>x.textContent=fmt(v));
 set('done',c.booked);set('total',t.length);set('booked',c.booked);set('pending',c.pending);set('not-booked',c['not-booked']);
 const LAB={booked:'booked',pending:'pending','not-booked':'not booked',cancelled:'cancelled'},seg=$1('[data-bento-seg]',tile);
 seg.innerHTML=Object.keys(c).filter(k=>c[k]).map(k=>`<i class="s-${k}" style="flex:${c[k]}"></i>`).join('');
 seg.setAttribute('role','img');seg.setAttribute('aria-label',t.length?Object.keys(c).filter(k=>c[k]).map(k=>c[k]+' '+LAB[k]).join(', '):'No bookings in the tracker');
 const r=Array.isArray(G.roster)?G.roster:[],av=$1('[data-bento-avatars]',tile);
 av.innerHTML=r.map(p=>`<span title="${escH(String(p.name||'').trim()||'?')}" aria-hidden="true">${escH(ini(p.name))}</span>`).join('');
 av.setAttribute('role','img');av.setAttribute('aria-label',r.length+' traveler'+(r.length===1?'':'s')+': '+r.map(p=>String(p.name||'').trim()||'(no name)').join(', '));
 $all('[data-bento-progress],[data-bento-seg],[data-bento-key],[data-bento-avatars]',tile).forEach(x=>x.hidden=false);
 $all('[data-bento-empty]',tile).forEach(x=>x.remove())}
function bentoHuts(){const ol=$1('[data-bento-huts]');if(!ol||typeof G==='undefined'||!G)return;
 const tr=Array.isArray(G.tracker)?G.tracker:[],nights=[];
 tr.forEach(r=>{const it=String(r.item||''),m=/hut night\s*(\d+)/i.exec(it),h=/^\s*(Rif(?:ugio|\.)\s+[^,(]+?)\s*(?:[,(]|$)/i.exec(it);if(m&&h)nights.push({n:+m[1],hut:h[1].replace(/^Rifugio\s+/i,'Rif. '),status:r.status})});
 if(!nights.length)D.stages.forEach((s,i)=>{if(!(s.hs||[]).length)return;const b=$1(`#d${i} [data-hut-badge]`),st=b&&b.dataset.status;
  nights.push({n:i+1,hut:String(s.hut).replace(/\s+[≈\d].*$/,''),key:st&&st!=='none'?st:'not-booked',text:b&&b.textContent||'Not booked'})});
 nights.sort((a,b)=>a.n-b.n);
 ol.innerHTML=nights.map(x=>{const [k,tx]=x.key?[x.key,x.text]:(STATUS[x.status]||['not-booked',String(x.status||'Not booked')]);
  return `<li><div><span>Night ${x.n}${dayName(x.n)?' · '+dayName(x.n):''}</span><b>${escH(x.hut)}</b></div><span class="badge" data-status="${k}">${escH(tx)}</span></li>`}).join('');
 ol.hidden=!nights.length;const e=$1('[data-bento-empty]',ol.closest('.tile'));if(e&&nights.length)e.remove()}
function bento(){try{bentoRoute();bentoBookings();bentoHuts()}catch(e){console.warn('bento',e)}}
if(typeof renderG==='function'){const _rg=renderG;renderG=function(){const r=_rg.apply(this,arguments);bento();return r}}
bento();

/* ---- Follow the day: chips + sparks mirror the selection; phone carousel swipe and desktop scroll select the day ---- */
let curDay=null,progUntil=0,followSel=false;
const lockScroll=ms=>{progUntil=Date.now()+(ms||900)};
function markDay(i){$all('.daychips a[data-day]').forEach(a=>a.setAttribute('aria-current',String(+a.dataset.day===i)));$all('[data-bento-sparks] .spark').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.day===i)))}
{const _sel=select;select=function(i,fromCard,noScroll){followSel=false;curDay=i;_sel(i,fromCard);markDay(i);
  if(!noScroll&&PHONE.matches&&i!=null){const r=days,d=document.getElementById('d'+i);const rb=r&&r.getBoundingClientRect(),db=d&&d.getBoundingClientRect();if(r&&d&&r.scrollWidth>r.clientWidth&&(db.left<rb.left-4||db.right>rb.right+4)){lockScroll();r.scrollTo({left:d.offsetLeft-r.offsetLeft-16,behavior:smooth()})}}}}
function follow(i){if(i===curDay||Date.now()<progUntil)return;select(i,false,true);followSel=true}  // a followed day never scrolls the carousel (that would hijack the swipe)
{const chips=$1('.daychips');if(chips)chips.addEventListener('click',e=>{const a=e.target.closest('a[data-day]');if(!a)return;e.preventDefault();const i=+a.dataset.day,d=document.getElementById('d'+i);
  lockScroll(1200);select(i);d.scrollIntoView({behavior:smooth(),block:PHONE.matches?'nearest':'center',inline:'center'})})}
if(window.IntersectionObserver){
 // phone: pick the day once a swipe settles (scrollend; 150 ms after the last scroll event where scrollend is missing), never for cards crossed mid-swipe
 let swiped=false,settleT=0;
 const settle=()=>{clearTimeout(settleT);const user=swiped&&Date.now()>=progUntil;swiped=false;progUntil=Math.min(progUntil,Date.now()+60);
  if(!user||!PHONE.matches)return;const rb=days.getBoundingClientRect();let best=null,bw=0;
  $all('#days .day').forEach(d=>{const b=d.getBoundingClientRect(),w=Math.min(b.right,rb.right)-Math.max(b.left,rb.left);if(w>bw+1){bw=w;best=d}});
  if(best&&bw>=best.offsetWidth*.6)follow(+best.id.slice(1))};
 days.addEventListener('scroll',()=>{if(Date.now()>=progUntil)swiped=true;if(!('onscrollend' in window)){clearTimeout(settleT);settleT=setTimeout(settle,150)}},{passive:true});
 days.addEventListener('scrollend',settle);
 const ioDesk=new IntersectionObserver(es=>{if(PHONE.matches)return;
   // one winner per batch: the target covering most of the band (a fast scroll can report two at once)
   const e=es.filter(x=>x.isIntersecting).sort((a,b)=>b.intersectionRect.height-a.intersectionRect.height)[0];
   if(!e){const d0=$1('#d0');if(d0&&followSel&&curDay!==null&&Date.now()>=progUntil&&d0.getBoundingClientRect().top>innerHeight*.5){select(null);followSel=true}return}  // jumped back above the first day (Home key, scroll to top)
   if(e.target.id==='bento'){if(followSel&&curDay!==null&&Date.now()>=progUntil){select(null);followSel=true}}else follow(+e.target.id.slice(1))},{rootMargin:'-45% 0px -50% 0px'});
 $all('#days .day').forEach(d=>ioDesk.observe(d));const bb=$1('#bento');if(bb)ioDesk.observe(bb)}

/* ---- View Transitions on tab change (skipped without support or with reduced motion) ---- */
{const _show=show;show=function(id,focus){const t=document.getElementById(id);
  if(!document.startViewTransition||reduceMotion||!t||t.getAttribute('aria-selected')==='true')return _show(id,focus);
  const vt=document.startViewTransition(()=>_show(id,focus));vt.ready.catch(()=>{});vt.finished.catch(()=>{});return vt}}

