function printDate(){const s=' · printed '+new Date().toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});$all('[data-print-date]').forEach(x=>x.textContent=s)}
printDate();addEventListener('beforeprint',printDate);
